/* From Uiverse.io by Yaya12085 - Tags: form */
.__UIV_SCOPE__ .container {
  height: 300px;
  width: 300px;
  border-radius: 10px;
  box-shadow: 4px 4px 30px rgba(0, 0, 0, .2);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  padding: 10px;
  gap: 5px;
  background-color: rgba(0, 110, 255, 0.041);
}

.__UIV_SCOPE__ .header {
  flex: 1;
  width: 100%;
  border: 2px dashed royalblue;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
}

.__UIV_SCOPE__ .header svg {
  height: 100px;
}

.__UIV_SCOPE__ .header p {
  text-align: center;
  color: black;
}

.__UIV_SCOPE__ .footer {
  background-color: rgba(0, 110, 255, 0.075);
  width: 100%;
  height: 40px;
  padding: 8px;
  border-radius: 10px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  color: black;
  border: none;
}

.__UIV_SCOPE__ .footer svg {
  height: 130%;
  fill: royalblue;
  background-color: rgba(70, 66, 66, 0.103);
  border-radius: 50%;
  padding: 2px;
  cursor: pointer;
  box-shadow: 0 2px 30px rgba(0, 0, 0, 0.205);
}

.__UIV_SCOPE__ .footer p {
  flex: 1;
  text-align: center;
}

.__UIV_SCOPE__ #file {
  display: none;
}
